import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../core/opdesk_repository.dart';
import '../../core/api_client.dart';
class DailyUpdatesScreen extends StatefulWidget{const DailyUpdatesScreen({super.key});@override State<DailyUpdatesScreen> createState()=>_S();}
class _S extends State<DailyUpdatesScreen>{final worked=TextEditingController(),completed=TextEditingController(),next=TextEditingController(),blockers=TextEditingController();List<dynamic> items=[];bool busy=false;@override void initState(){super.initState();load();}Future<void>load()async{try{final d=await context.read<OpDeskRepository>().getRaw('/api/daily-updates');if(mounted)setState(()=>items=d['updates']??[]);}catch(_){} }Future<void>submit()async{setState(()=>busy=true);try{await context.read<OpDeskRepository>().postRaw('/api/daily-updates',{'workedOn':worked.text,'completed':completed.text,'nextWork':next.text,'blockers':blockers.text});worked.clear();completed.clear();next.clear();blockers.clear();await load();}on ApiException catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.message)));}finally{if(mounted)setState(()=>busy=false);}}Widget f(String h,TextEditingController c)=>Padding(padding:const EdgeInsets.only(bottom:10),child:TextField(controller:c,maxLines:3,decoration:InputDecoration(labelText:h,border:OutlineInputBorder(borderRadius:BorderRadius.circular(12)))));@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Daily Updates'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),body:RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(16),children:[const Text('Today’s update',style:TextStyle(fontSize:22,fontWeight:FontWeight.w800)),const SizedBox(height:14),f('What did you work on?',worked),f('What did you complete?',completed),f('What will you work on next?',next),f('Blockers / support needed',blockers),FilledButton.icon(onPressed:busy?null:submit,icon:const Icon(Icons.send),label:const Text('Submit daily update')),const SizedBox(height:22),const Text('Recent updates',style:TextStyle(fontSize:18,fontWeight:FontWeight.w800)),...items.take(10).map((x)=>Card(elevation:0,child:ListTile(title:Text((x['workedOn']??'Update').toString()),subtitle:Text((x['completed']??'').toString()))))])));}
